namespace Arrow.Common.Generation;

/// <summary>
/// A c0 given by <c>arrow gen --c0</c> instead of generated by the model (P04 §6.8, Chính 20/11/2026): an existing test suite to verify
/// and repair, e.g. a frozen c0 of the team's TN1 that every branch of TN2 repairs. In <c>run.json</c> <c>config.c0</c>; its code is
/// kept in the run as <see cref="RunCopy"/>, so that <c>--resume</c> does not need the file any more.
/// </summary>
/// <param name="File">The file as typed, made absolute.</param>
/// <param name="Sha256">sha256 of the bytes of the file.</param>
/// <param name="GenerationModel"><c>--c0-model</c>: who wrote the suite, a free label (e.g. <c>gpt6luna</c>); null when unknown.</param>
/// <param name="PreviousState"><c>--c0-state</c>: its state when it was made (e.g. in TN1); null when not given.</param>
public sealed record C0File(string File, string Sha256, string? GenerationModel, VerificationState? PreviousState)
{
    /// <summary>Copy of the code in the run folder.</summary>
    public const string RunCopy = "c0_input.java";

    /// <summary>Value of <c>c0_source</c> for a c0 the model generated.</summary>
    public const string Generated = "generated";

    /// <summary>Value of <c>c0_source</c> for a c0 of <c>--c0</c>.</summary>
    public const string FromFile = "file";

    /// <summary>Largest file accepted, in bytes.</summary>
    public const int MaxBytes = 1024 * 1024;

    /// <summary>
    /// <c>same_model</c> of <c>final.json</c> and <c>decision.json</c>: whether the repair model is the generation model; null when the
    /// generation model is unknown.
    /// </summary>
    public static bool? SameModel(string? generationModel, string repairModel) =>
        generationModel is null ? null : string.Equals(generationModel, repairModel, StringComparison.Ordinal);
}
